const generated: MidtermQuestion[] = [];
let nextId = 51;
const add = (question: Omit<MidtermQuestion, 'id'>) => {
  const id = nextId++;
  if (!question.options?.length || !question.answer?.length) {
    generated.push({id,...question});
    return;
  }
  const offset = id % question.options.length;
  const options = [...question.options.slice(offset),...question.options.slice(0,offset)];
  const answer = question.answer.map((index) => (index-offset+question.options!.length)%question.options!.length).sort((a,b)=>a-b);
  generated.push({id,...question,options,answer});
};

for (const [scenarioIndex,item] of scenarios.entries()) {
  add({kind:'single',day:item.day,topic:item.topic,prompt:`${item.situation} Cách xử lý phù hợp nhất là gì?`,options:[item.action,...item.distractors],answer:[0],explanation:item.correction});
  add({kind:'multiple',day:item.day,topic:item.topic,prompt:`${item.situation} Chọn các evidence cần giữ để người khác review được quyết định.`,options:[item.evidence[0],item.evidence[1],...item.noise],answer:[0,1],explanation:'Evidence cần có ngữ cảnh và nguồn kiểm chứng; tín hiệu phụ không thay thế record có thể audit.'});
  const correctStatement = scenarioIndex%2===0;
  add({kind:'boolean',day:item.day,topic:item.topic,prompt:correctStatement?`Đúng hay sai? ${item.action}`:`Đúng hay sai? ${item.misconception}`,options:['Đúng','Sai'],answer:[correctStatement?0:1],explanation:item.correction});
  add({kind:'written',day:item.day,topic:item.topic,prompt:`${item.situation} Hãy ghi ngắn gọn quyết định của bạn, evidence cần kiểm tra và cách ngăn lỗi lặp lại.`,explanation:'Tự đối chiếu theo các ý chính bên dưới.',rubric:[item.action,item.evidence[0],item.evidence[1]]});
}

const metricCases = [
  [18,6,12],[24,8,6],[15,5,10],[32,8,16],[21,9,7],[40,10,20],[12,3,9],[27,3,12],[36,12,18],[16,4,4],
  [25,5,15],[14,7,7],[30,10,5],[45,15,15],[20,5,15],[28,7,14],[10,2,8],[33,11,6],[22,8,10],[48,12,8],
  [17,3,7],[26,4,13],[35,5,10],[19,11,5],[42,8,21],
];
const percent = (n:number) => `${Math.round(n*100)}%`;
metricCases.forEach(([tp,fp,fn],i) => {
  const p = tp/(tp+fp), r = tp/(tp+fn), f1 = 2*p*r/(p+r);
  const ask = i%3;
  const prompt = ask===0 ? `Slice ${i+1}: TP=${tp}, FP=${fp}, FN=${fn}. Precision của detector là bao nhiêu?` : ask===1 ? `Slice ${i+1}: TP=${tp}, FP=${fp}, FN=${fn}. Recall của detector là bao nhiêu?` : `Slice ${i+1}: TP=${tp}, FP=${fp}, FN=${fn}. F1-score xấp xỉ bao nhiêu?`;
  const correct = ask===0?percent(p):ask===1?percent(r):percent(f1);
  const options = [correct,percent(ask===0?r:ask===1?p:f1*0.75),percent(ask===0?tp/(tp+fn+fp):ask===1?tp/(tp+fp+fn):Math.abs(p-r)),percent(ask===0?p*0.8:ask===1?r*0.8:f1*1.5)];
  add({kind:'single',day:'Ngày 02',topic:'Detection metrics',prompt,options:[...new Set(options)].slice(0,4),answer:[0],explanation:`${ask===0?'Precision = TP/(TP+FP)':ask===1?'Recall = TP/(TP+FN)':'F1 = 2 × precision × recall / (precision + recall)'}. Với TP=${tp}, FP=${fp}, FN=${fn}, kết quả xấp xỉ ${correct}.`});
});

const iouCases = [
  [100,100,50],[120,80,40],[64,64,32],[150,100,75],[90,60,30],[200,120,60],[80,50,20],[144,96,48],[110,70,35],[180,120,90],
  [75,75,25],[160,100,80],[96,72,36],[210,140,70],[125,100,50],[240,160,120],[88,66,22],[132,88,44],[300,200,100],[105,70,21],
  [128,96,64],[175,125,75],[192,128,96],[84,56,28],[225,150,75],
];
iouCases.forEach(([areaA,areaB,intersection],i) => {
  const union = areaA+areaB-intersection;
  const iou = intersection/union;
  const correct = percent(iou);
  const distractors = [percent(intersection/Math.max(areaA,areaB)),percent(intersection/(areaA+areaB)),percent(union/(areaA+areaB))];
  const options = [correct,...distractors].filter((v,n,a)=>a.indexOf(v)===n).slice(0,4);
  add({kind:'single',day:'Ngày 02',topic:'IoU / bounding box',prompt:`Case box ${i+1}: diện tích box dự đoán=${areaA}, ground truth=${areaB}, phần giao=${intersection}. IoU bằng bao nhiêu?`,options,answer:[0],explanation:`IoU = intersection / union; union = ${areaA} + ${areaB} − ${intersection} = ${union}. Kết quả xấp xỉ ${correct}.`});
});

export const dataTrackQuestions: MidtermQuestion[] = [...midtermQuestions,...generated];
export const dataTrackQuestionCount = dataTrackQuestions.length;

export const questionKinds = ['single','multiple','boolean','written'] as const;

function shuffle<T>(items: T[], random: () => number): T[] {
  const result = [...items];
  for (let index = result.length - 1; index > 0; index -= 1) {
    const target = Math.floor(random() * (index + 1));
    [result[index],result[target]] = [result[target],result[index]];
  }
  return result;
}

export function pickExamQuestions(random = Math.random, excludedIds: number[] = []): MidtermQuestion[] {
  const quotas: Record<MidtermQuestion['kind'], number> = {single:30,multiple:8,boolean:6,written:6};
  const excluded = new Set(excludedIds);
  const picked = questionKinds.flatMap((kind) => {
    const fullPool = dataTrackQuestions.filter((question) => question.kind === kind);
    const unseenPool = fullPool.filter((question) => !excluded.has(question.id));
    const pool = unseenPool.length >= quotas[kind] ? unseenPool : fullPool;
    return shuffle(pool,random).slice(0,quotas[kind]);
  });
  return shuffle(picked,random);
}
